// EXPORTS: fetchWithCache, clearCache, clearAllCache, getCacheMeta, DEFAULT_TTL
import { scopedStorage, logger } from '@lark-apaas/client-toolkit-lite';
import api from './api';

export const DEFAULT_TTL = 10 * 60 * 1000; // 10 分钟
export const SEARCH_TTL = 3 * 60 * 1000; // 搜索类 3 分钟
export const LOCATION_TTL = 24 * 60 * 60 * 1000; // 定位 24 小时

const STORAGE_PREFIX = 'cache:';

export interface CacheMeta {
  key: string;
  timestamp: number;
  ttl: number;
  size: number;
}

interface CacheEntry<T = unknown> {
  t: number; // timestamp
  d: T; // data
  ttl: number;
}

function buildKey(rawKey: string): string {
  return `${STORAGE_PREFIX}${rawKey}`;
}

function readEntry<T>(key: string): CacheEntry<T> | null {
  try {
    const raw = scopedStorage.getItem(buildKey(key));
    if (!raw) return null;
    return JSON.parse(raw) as CacheEntry<T>;
  } catch (err) {
    logger.warn('cache read fail:', key, String(err));
    return null;
  }
}

function writeEntry<T>(key: string, data: T, ttl: number) {
  try {
    const entry: CacheEntry<T> = { t: Date.now(), d: data, ttl };
    scopedStorage.setItem(buildKey(key), JSON.stringify(entry));
  } catch (err) {
    logger.warn('cache write fail:', key, String(err));
    // 存储满了清掉最旧的 5 条
    try {
      cleanupOld(5);
      const entry: CacheEntry<T> = { t: Date.now(), d: data, ttl };
      scopedStorage.setItem(buildKey(key), JSON.stringify(entry));
    } catch {
      // 彻底失败就放弃缓存
    }
  }
}

function cleanupOld(count: number) {
  const entries: { key: string; t: number }[] = [];
  for (let i = 0; i < scopedStorage.length; i++) {
    const k = scopedStorage.key(i);
    if (!k || !k.startsWith(STORAGE_PREFIX)) continue;
    try {
      const raw = scopedStorage.getItem(k);
      if (!raw) continue;
      const parsed = JSON.parse(raw) as { t: number };
      entries.push({ key: k, t: parsed.t });
    } catch {
      // ignore
    }
  }
  entries.sort((a, b) => a.t - b.t);
  entries.slice(0, count).forEach(e => {
    try {
      scopedStorage.removeItem(e.key);
    } catch {
      // ignore
    }
  });
}

export interface FetchWithCacheOptions {
  /** 过期时间，毫秒。默认 10 分钟 */
  ttl?: number;
  /** 强制刷新，绕过缓存直接联网 */
  force?: boolean;
  /** HTTP 方法，默认 get */
  method?: 'get' | 'post';
  /** POST body 或 GET params（get 时自动转 querystring） */
  data?: Record<string, unknown>;
  /** 自定义错误处理（不抛错则返回 null） */
  onError?: (err: unknown) => void;
}

export interface FetchWithCacheResult<T> {
  data: T;
  cached: boolean;
  timestamp: number;
}

/**
 * 统一联网缓存层。
 * - key 存在且未过期 → 返回缓存，cached: true
 * - 过期 / 不存在 / force=true → 真实请求，成功写缓存，cached: false
 * - 联网失败 → 若有缓存则降级返回缓存（stale-while-error），无缓存则抛出原错误
 */
export async function fetchWithCache<T = unknown>(
  key: string,
  url: string,
  options: FetchWithCacheOptions = {},
): Promise<FetchWithCacheResult<T>> {
  const { ttl = DEFAULT_TTL, force = false, method = 'get', data, onError } = options;

  // 1. 读缓存（非强制模式）
  if (!force) {
    const entry = readEntry<T>(key);
    if (entry && Date.now() - entry.t < entry.ttl) {
      return { data: entry.d, cached: true, timestamp: entry.t };
    }
  }

  // 2. 发起真实请求
  try {
    let res: { data: T };
    if (method === 'get') {
      res = await api.get(url, { params: data });
    } else {
      res = await api.post(url, data);
    }
    const result = res.data as T;
    writeEntry(key, result, ttl);
    return { data: result, cached: false, timestamp: Date.now() };
  } catch (err) {
    // 3. 联网失败：有缓存则 stale-while-error 降级
    const stale = readEntry<T>(key);
    if (stale) {
      logger.info('cache stale fallback:', key);
      onError?.(err);
      return { data: stale.d, cached: true, timestamp: stale.t };
    }
    onError?.(err);
    throw err;
  }
}

/** 清除指定 key 的缓存 */
export function clearCache(key: string) {
  try {
    scopedStorage.removeItem(buildKey(key));
  } catch {
    // ignore
  }
}

/** 清除所有缓存（全部以 cache: 开头） */
export function clearAllCache() {
  try {
    const keys: string[] = [];
    for (let i = 0; i < scopedStorage.length; i++) {
      const k = scopedStorage.key(i);
      if (k?.startsWith(STORAGE_PREFIX)) keys.push(k);
    }
    keys.forEach(k => scopedStorage.removeItem(k));
  } catch {
    // ignore
  }
}

/** 获取缓存元信息（上次更新时间等），用于展示「上次更新 xx:xx」 */
export function getCacheMeta(key: string): CacheMeta | null {
  const entry = readEntry(key);
  if (!entry) return null;
  try {
    const size = JSON.stringify(entry).length;
    return { key, timestamp: entry.t, ttl: entry.ttl, size };
  } catch {
    return null;
  }
}

/** 格式化时间戳为「HH:mm」 */
export function formatCacheTime(ts: number | null | undefined): string {
  if (!ts) return '';
  const d = new Date(ts);
  const h = String(d.getHours()).padStart(2, '0');
  const m = String(d.getMinutes()).padStart(2, '0');
  return `${h}:${m}`;
}
